// Vercel Edge Middleware — no external imports needed

// --- Rate Limiting (in-memory, per-edge-region) ---
const rateMap = new Map();
const RATE_LIMIT = 60;       // max requests
const RATE_WINDOW = 60_000;  // per 60 seconds

function isRateLimited(ip) {
  const now = Date.now();
  const entry = rateMap.get(ip);
  if (!entry || now - entry.start > RATE_WINDOW) {
    rateMap.set(ip, { start: now, count: 1 });
    return false;
  }
  entry.count++;
  if (entry.count > RATE_LIMIT) return true;
  return false;
}

// --- Known bot user-agents ---
const BOT_PATTERNS = [
  /bot/i, /crawl/i, /spider/i, /scrape/i, /wget/i, /curl/i,
  /python-requests/i, /httpx/i, /aiohttp/i, /scrapy/i, /puppeteer/i,
  /playwright/i, /headless/i, /phantom/i, /selenium/i, /chrome-lighthouse/i,
  /HTTrack/i, /axios/i, /node-fetch/i, /go-http-client/i, /java\//i,
  /libwww/i, /lwp-trivial/i, /mechanize/i, /http_request/i,
];

// Allow legitimate bots you want (Google, Bing, etc.) — remove if you want to block ALL bots
const ALLOWED_BOTS = [
  // Uncomment if you want search engines to index your site:
  // /googlebot/i, /bingbot/i, /yandexbot/i, /duckduckbot/i,
];

function isBot(ua) {
  if (!ua) return true; // No user-agent = suspicious
  for (const allowed of ALLOWED_BOTS) {
    if (allowed.test(ua)) return false;
  }
  for (const pattern of BOT_PATTERNS) {
    if (pattern.test(ua)) return true;
  }
  return false;
}

// --- Honeypot detection ---
const bannedIPs = new Set();

export default function middleware(request) {
  const url = new URL(request.url);
  const ip = request.headers.get('x-forwarded-for')?.split(',')[0]?.trim() || 'unknown';
  const ua = request.headers.get('user-agent') || '';

  // Honeypot trap — instant ban
  if (url.pathname === '/.secret-data' || url.pathname === '/.admin') {
    bannedIPs.add(ip);
    return new Response('Not Found', { status: 404 });
  }

  // Check if IP is banned
  if (bannedIPs.has(ip)) {
    return new Response('Access Denied', { status: 403 });
  }

  // Bot detection
  if (isBot(ua)) {
    return new Response('Access Denied', {
      status: 403,
      headers: { 'Content-Type': 'text/plain' },
    });
  }

  // Rate limiting
  if (isRateLimited(ip)) {
    return new Response('Too Many Requests. Please slow down.', {
      status: 429,
      headers: {
        'Retry-After': '60',
        'Content-Type': 'text/plain',
      },
    });
  }

  // Add security headers to all responses
  const response = next();
  const headers = new Headers();
  headers.set('X-Robots-Tag', 'noindex, nofollow, noarchive, nosnippet');
  headers.set('X-Content-Type-Options', 'nosniff');
  headers.set('X-Frame-Options', 'DENY');
  headers.set('Referrer-Policy', 'no-referrer');
  headers.set('Permissions-Policy', 'camera=(), microphone=(), geolocation=()');
  headers.set('Cache-Control', 'no-store, no-cache, must-revalidate, private');

  return new Response(response.body, {
    status: response.status,
    statusText: response.statusText,
    headers: { ...Object.fromEntries(response.headers), ...Object.fromEntries(headers) },
  });
}

export const config = {
  matcher: ['/((?!_next/static|_next/image|favicon.ico).*)'],
};

