1883→    function buildVerticalList() {
1884→      const CAGRS = { data_center: '18.5%', healthcare: '7.4%', industrial: '12.1%', education: '5.2%', multifamily: '8.4%', office: '3.2%', hospitality: '6.1%', government: '6.1%' };
1885→      const TAGS = { data_center: { t: 'hot', l: '🔥 HOT' }, healthcare: { t: 'cool', l: '+7.4%' }, industrial: { t: 'warm', l: '+12.1%' }, education: { t: 'cool', l: '+5.2%' }, multifamily: { t: 'cool', l: '+8.4%' }, office: { t: 'warm', l: 'Moderate' }, hospitality: { t: 'cool', l: '+6.1%' }, government: { t: 'cool', l: '+6.1%' } };
1886→      document.getElementById('v-list').innerHTML = Object.entries(VERTICALS).map(([k, v]) => {
1887→        const tg = TAGS[k];
1888→        return `<button class="v-btn${k === activeVertical ? ' active' : ''}" data-v="${k}" onclick="setVertical(this,'${k}')">
1889→      <div class="v-icon-box" style="background:${v.color}18">${v.icon}</div>
