1892→    </button>`;
1893→      }).join('');
1894→    }
1895→
1896→    /* ═══════════════════════════════════════
1897→       STATE HEATMAP LAYER
1898→    ═══════════════════════════════════════ */
1899→    async function loadStateLayer() {
1900→      const resp = await fetch('https://cdn.jsdelivr.net/npm/us-atlas@3/states-10m.json');
1901→      const us = await resp.json();
1902→      const geo = topojson.feature(us, us.objects.states);
1903→      stateLayer = L.geoJSON(geo, {
1904→        style: stateStyle,
1905→        onEachFeature: (feat, layer) => {
1906→          layer.on({ mouseover: onStateHover, mousemove: onStateMove, mouseout: onStateOut, click: onStateClick });
1907→        }
1908→      });
1909→      if (heatVisible) stateLayer.addTo(map);
1910→    }
1911→    function stateStyle(feat) {
1912→      const code = FIPS[feat.id.toString().padStart(2, '0')];
1913→      if (!code || !STATE_DATA[code]) return { fillColor: '#0b1220', fillOpacity: .7, color: '#192840', weight: .8 };
1914→      return { fillColor: scoreColor(getScore(code, activeVertical, activeYear)), fillOpacity: .72, color: '#0a1828', weight: .6 };
1915→    }
1916→    function recolorStates() { if (stateLayer) stateLayer.setStyle(stateStyle) }
1917→
1918→    /* ═══════════════════════════════════════
1919→       STATE HOVER / CLICK
1920→    ═══════════════════════════════════════ */
1921→    const mapTT = document.getElementById('map-tooltip');
1922→    function onStateHover(e) {
1923→      e.target.setStyle({ weight: 2, color: '#00c8f0', fillOpacity: .88 });
1924→      e.target.bringToFront();
1925→      const code = FIPS[e.target.feature.id.toString().padStart(2, '0')];
1926→      if (!code || !STATE_DATA[code]) { mapTT.classList.remove('show'); return; }
1927→      const s = STATE_DATA[code];
1928→      const score = getScore(code, activeVertical, activeYear);
1929→      const vol = Math.round(getVol(activeVertical, code) * YF[activeYear][activeVertical]);
1930→      const topV = Object.keys(VERTICALS).reduce((a, b) => getScore(code, a, activeYear) > getScore(code, b, activeYear) ? a : b);
1931→      const tCount = ALL_REPS.filter(r => r.state === code && r.brand === 'titus').length;
1932→      const kCount = ALL_REPS.filter(r => r.state === code && r.brand === 'krueger').length;
1933→      mapTT.innerHTML = `<div class="mtt-name">${s.name}</div>
1934→    <div class="mtt-row"><span>${VERTICALS[activeVertical].icon} ${VERTICALS[activeVertical].label}</span><b>${score}/100</b></div>
1935→    <div class="mtt-row"><span>Est. Volume</span><b>$${vol}M</b></div>
1936→    <div class="mtt-row"><span>Top Vertical</span><b>${VERTICALS[topV].icon} ${VERTICALS[topV].label}</b></div>
1937→    <div class="mtt-row"><span style="color:var(--titus)">● Titus</span><b style="color:var(--titus)">${tCount} loc${tCount !== 1 ? 's' : ''}</b></div>
1938→    <div class="mtt-row"><span style="color:var(--krueger)">● Krueger</span><b style="color:var(--krueger)">${kCount} loc${kCount !== 1 ? 's' : ''}</b></div>
1939→    <div class="mtt-hint">Click for full intelligence →</div>`;
1940→      mapTT.classList.add('show');
1941→    }
1942→    function onStateMove(e) {
