1947→    }
1948→    function onStateOut(e) { if (stateLayer) stateLayer.resetStyle(e.target); mapTT.classList.remove('show'); }
1949→    function onStateClick(e) {
1950→      const code = FIPS[e.target.feature.id.toString().padStart(2, '0')];
