1987→    ${r.email ? `<div class="pop-row"><span class="pi">✉️</span><a href="mailto:${r.email}">${r.email}</a></div>` : ''}
1988→    ${r.web ? `<div class="pop-row"><span class="pi">🌐</span><a href="${r.web.startsWith('http') ? r.web : 'http://' + r.web}" target="_blank" rel="noopener">${r.web.replace(/https?:\/\//, '').replace(/\\/g, '/')}</a></div>` : ''}
