const DB = require('./db.json');
const BRANDS = DB.brands;

function norm(s) {
  return s.toLowerCase().replace(/[\s\-_\/]+/g, '');
}

// Build search index once (persists across warm invocations)
let IDX = null;
function getIndex() {
  if (IDX) return IDX;
  IDX = new Map();
  function addKey(key, ri) {
    if (!key) return;
    if (!IDX.has(key)) IDX.set(key, new Set());
    IDX.get(key).add(ri);
  }
  DB.data.forEach(function (row, ri) {
    BRANDS.forEach(function (b) {
      if (!row[b]) return;
      row[b].split(/[\/,]/).forEach(function (m) {
        var key = norm(m.trim());
        addKey(key, ri);
      });
    });
    if (row.description) {
      addKey(norm(row.description), ri);
    }
  });
  return IDX;
}

module.exports = function handler(req, res) {
  const q = (req.query.q || '').trim();
  if (!q) {
    return res.status(400).json({ error: 'Missing query parameter q' });
  }
  if (q.length < 2) {
    return res.status(400).json({ error: 'Query too short' });
  }

  const idx = getIndex();
  const nq = norm(q);
  const matchedRows = new Set();

  // Exact prefix match on index keys
  for (const [key, rowSet] of idx) {
    if (key.includes(nq)) {
      for (const ri of rowSet) matchedRows.add(ri);
    }
  }

  // Limit results to prevent data dumping
  const MAX_RESULTS = 50;
  const results = [];
  let count = 0;
  for (const ri of matchedRows) {
    if (count >= MAX_RESULTS) break;
    const row = DB.data[ri];
    // Only return brands that have data for this row
    const entry = {
      category: row.category,
      dataset: row.dataset,
      description: row.description,
      brands: {},
    };
    BRANDS.forEach(function (b) {
      if (row[b]) entry.brands[b] = row[b];
    });
    results.push(entry);
    count++;
  }

  res.setHeader('Cache-Control', 'no-store');
  res.setHeader('X-Robots-Tag', 'noindex');
  return res.status(200).json({
    query: q,
    total: matchedRows.size,
    showing: results.length,
    results: results,
  });
};

