const BRANDS = DB.brands;

module.exports = function handler(req, res) {
  const category = (req.query.category || '').trim();
  const brandsParam = (req.query.brands || '').trim();

  if (!category) {
    return res.status(400).json({ error: 'Missing category parameter' });
  }

  const selectedBrands = brandsParam ? brandsParam.split(',').map(b => b.trim()) : [];

  // Filter rows by category
  const rows = DB.data.filter(r => r.category === category);

  // Limit output
  const MAX_ROWS = 100;
  const results = rows.slice(0, MAX_ROWS).map(row => {
    const entry = {
      description: row.description,
      brands: {},
    };
    const brandsToShow = selectedBrands.length > 0 ? selectedBrands : BRANDS;
    brandsToShow.forEach(b => {
      if (row[b]) entry.brands[b] = row[b];
    });
    return entry;
  });

  res.setHeader('Cache-Control', 'no-store');
  res.setHeader('X-Robots-Tag', 'noindex');
  return res.status(200).json({
    category: category,
    total: rows.length,
    showing: results.length,
    results: results,
  });
};

