326→function levenshtein(a, b) {
327→  var m = a.length, n = b.length;
328→  var dp = [];
329→  for (var i = 0; i <= m; i++) { dp[i] = [i]; }
330→  for (var j = 0; j <= n; j++) { dp[0][j] = j; }
331→  for (var i = 1; i <= m; i++) {
332→    for (var j = 1; j <= n; j++) {
333→      dp[i][j] = a[i-1] === b[j-1]
334→        ? dp[i-1][j-1]
335→        : 1 + Math.min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]);
336→    }
337→  }
338→  return dp[m][n];
339→}
