const fs = require('fs');
const html = fs.readFileSync('index.html', 'utf8');

// Extract all data constants from the script section
const scriptStart = html.indexOf('<script>');
const scriptEnd = html.indexOf('</script>', scriptStart);
const script = html.substring(scriptStart + 8, scriptEnd);

// Find each constant
function extractConst(name) {
  const start = script.indexOf('const ' + name + ' =');
  if (start === -1) return null;
  const valueStart = script.indexOf('=', start) + 1;
  // Find the semicolon that ends the declaration
  let depth = 0; let i = valueStart; let foundStart = false;
  for (; i < script.length; i++) {
    if (script[i] === '{' || script[i] === '[') { depth++; foundStart = true; }
    else if (script[i] === '}' || script[i] === ']') { depth--; }
    if (foundStart && depth === 0) break;
  }
  return script.substring(valueStart, i + 1).trim();
}

// Extract and save all data
const data = {
  VERTICALS: eval('(' + extractConst('VERTICALS') + ')'),
  STATE_DATA: eval('(' + extractConst('STATE_DATA') + ')'),
  YF: eval('(' + extractConst('YF') + ')'),
  BV: eval('(' + extractConst('BV') + ')'),
  FIPS: eval('(' + extractConst('FIPS') + ')'),
  BRAND_COLOR: eval('(' + extractConst('BRAND_COLOR') + ')'),
  BRAND_GLOW: eval('(' + extractConst('BRAND_GLOW') + ')'),
  TITUS_REPS: eval('(' + extractConst('TITUS_REPS') + ')'),
  KRUEGER_REPS: eval('(' + extractConst('KRUEGER_REPS') + ')'),
};

console.log('VERTICALS:', Object.keys(data.VERTICALS).length, 'entries');
console.log('STATE_DATA:', Object.keys(data.STATE_DATA).length, 'states');
console.log('TITUS_REPS:', data.TITUS_REPS.length, 'reps');
console.log('KRUEGER_REPS:', data.KRUEGER_REPS.length, 'reps');

fs.writeFileSync('atlas-data.json', JSON.stringify(data));
console.log('Saved atlas-data.json:', (fs.statSync('atlas-data.json').size / 1024).toFixed(0), 'KB');
"

