const data = require('./atlas-data.json');

module.exports = function handler(req, res) {
  const brand = (req.query.brand || '').toLowerCase();
  const state = (req.query.state || '').toUpperCase();
  const region = (req.query.region || '');

  let reps = [...data.TITUS_REPS, ...data.KRUEGER_REPS];

  // Filter by brand
  if (brand && brand !== 'all') {
    reps = reps.filter(r => r.brand === brand);
  }

  // Filter by state
  if (state && state !== 'ALL') {
    reps = reps.filter(r => r.state === state);
  }

  // Filter by region
  if (region && region !== 'ALL') {
    reps = reps.filter(r => r.region === region);
  }

  // Limit results
  const MAX_RESULTS = 80;
  const total = reps.length;
  reps = reps.slice(0, MAX_RESULTS);

  res.setHeader('Cache-Control', 'no-store');
  res.setHeader('X-Robots-Tag', 'noindex');
  return res.status(200).json({
    total: total,
    showing: reps.length,
    reps: reps,
  });
};

