const fs = require('fs');
const html = fs.readFileSync('new-atlas.html', 'utf8');
const script = html.substring(html.indexOf('<script>') + 8, html.lastIndexOf('</script>'));

function extractConst(name) {
  const pat = 'const ' + name + ' =';
  const start = script.indexOf(pat);
  if (start === -1) return null;
  const valueStart = script.indexOf('=', start) + 1;
  let depth = 0; let i = valueStart; let foundStart = false;
  for (; i < script.length; i++) {
    if (script[i] === '{' || script[i] === '[') { depth++; foundStart = true; }
    else if (script[i] === '}' || script[i] === ']') { depth--; }
    if (foundStart && depth === 0) break;
  }
  return script.substring(valueStart, i + 1).trim();
}

const names = ['VERTICALS','STATE_DATA','YF','BV','FIPS','BRAND_COLOR','BRAND_GLOW',
  'TITUS_REPS','KRUEGER_REPS','GREENHECK_REPS','LORENCOOK_REPS','POTTORFF_REPS',
  'EHPRICE_REPS','RUSKIN_REPS','PENNBARRY_REPS','TUTTLEBAILEY_REPS'];

