const fs = require('fs');
const htmlShell = fs.readFileSync('html-shell.txt', 'utf8');
const appLogic = fs.readFileSync('app-logic-new.txt', 'utf8');

// Build the boot loader that fetches data from APIs before running app logic
const bootLoader = \`
// ══════════════════════════════════════
// DATA - loaded from API (not inline)
// ══════════════════════════════════════
let VERTICALS = {};
let STATE_DATA = {};
let YF = {};
let BV = {};
let FIPS = {};
let BRAND_COLOR = {};
let BRAND_GLOW = {};
let TITUS_REPS = [];
let KRUEGER_REPS = [];
let GREENHECK_REPS = [];
let LORENCOOK_REPS = [];
let POTTORFF_REPS = [];
let EHPRICE_REPS = [];
let RUSKIN_REPS = [];
let PENNBARRY_REPS = [];
let TUTTLEBAILEY_REPS = [];
let ALL_REPS = [];
\`;

// The app logic uses 'const' for some variables - change to 'let' for the ones declared in boot
// Also need to wrap the boot sequence in an async function

// Find the BOOT section in app logic
const bootIdx = appLogic.indexOf('/* ═══════════════════');
const lastBootIdx = appLogic.lastIndexOf('/* ═══════════════════');

// Find where the boot calls are (buildVerticalList, loadStateLayer, etc.)
const buildVertIdx = appLogic.lastIndexOf('buildVerticalList()');
const renderPinsIdx = appLogic.indexOf('renderPins()', buildVertIdx);
const afterRenderPins = appLogic.indexOf('\\n', renderPinsIdx);

// Split: app functions + boot section
const appFunctions = appLogic.substring(0, buildVertIdx);
const bootCalls = appLogic.substring(buildVertIdx, afterRenderPins + 1);
const afterBoot = appLogic.substring(afterRenderPins + 1);

const newScript = bootLoader + '\\n' + appFunctions + \`
// ══════════════════════════════════════
// BOOT - Load data from APIs then render
// ══════════════════════════════════════
(async function boot() {
  try {
    const [statesResp, repsResp] = await Promise.all([
      fetch('/api/states'),
      fetch('/api/reps')
    ]);
    const statesData = await statesResp.json();
    const repsData = await repsResp.json();

    VERTICALS = statesData.verticals;
    STATE_DATA = statesData.stateData;
    YF = statesData.yf;
