const fs = require('fs');
const html = fs.readFileSync('4.1.26_crossref-tool.html', 'utf8');

// Find DB
const dbStart = html.indexOf('const DB = ');
if (dbStart === -1) { console.log('No DB found'); process.exit(1); }
const valueStart = dbStart + 'const DB = '.length;
let depth = 0, i = valueStart, foundStart = false;
for (; i < html.length; i++) {
  if (html[i] === '{') { depth++; foundStart = true; }
  else if (html[i] === '}') { depth--; }
  if (foundStart && depth === 0) break;
}
const dbJson = html.substring(valueStart, i + 1);
const db = JSON.parse(dbJson);
console.log('Brands:', db.brands.length);
console.log('Data entries:', db.data.length);
console.log('DB size:', (dbJson.length / 1024).toFixed(0), 'KB');

// Save DB
fs.writeFileSync('db-new.json', dbJson);

// Find script tags
let pos = 0; let idx = 0;
while (true) {
  const start = html.indexOf('<script', pos);
  if (start === -1) break;
  const end = html.indexOf('</script>', start);
  const line = html.substring(0, start).split('\n').length;
  console.log('Script #' + idx + ' at line', line, 'length:', (end - start));
  pos = end + 9;
  idx++;
}

// Extract HTML before script and JS after DB
const scriptStart = html.indexOf('<script>');
const scriptEnd = html.lastIndexOf('</script>');
const htmlBefore = html.substring(0, scriptStart);
const scriptContent = html.substring(scriptStart + 8, scriptEnd);

// Find end of DB
const afterDb = scriptContent.substring(i - (scriptStart + 8) + 2);
console.log('\\nApp logic length:', afterDb.length);
console.log('HTML shell length:', htmlBefore.length);

fs.writeFileSync('html-shell-new.txt', htmlBefore);
fs.writeFileSync('app-logic-new.txt', afterDb);
console.log('\\nFiles saved');
"

