const fs = require('fs');
let htmlShell = fs.readFileSync('html-shell-new.txt', 'utf8');
const appLogic = fs.readFileSync('app-logic-new.txt', 'utf8');

// Add meta tags
htmlShell = htmlShell.replace(
  '<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">',
  '<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<meta name=\"robots\" content=\"noindex, nofollow, noarchive, nosnippet\">\n<meta name=\"googlebot\" content=\"noindex, nofollow\">'
);

// Remove compare tab button if present
htmlShell = htmlShell.replace(
  /<button class=\"tab-btn\" data-tab=\"compare\">.*?<\/button>/,
  ''
);

// Remove compare tab pane if present
htmlShell = htmlShell.replace(
  /<!-- TAB 2: COMPARE -->[\s\S]*?<\/div>\s*<\/div>\s*<\/div>/m,
  '<!-- Compare tab removed -->'
);

// Add honeypot
const honeypot = '\n<a href=\"/.secret-data\" style=\"position:absolute;left:-9999px;opacity:0;height:0;width:0;overflow:hidden\" tabindex=\"-1\" aria-hidden=\"true\">Data Export</a>\n';

// Build the script
const bootScript = \`<script>
// Anti-scraping
document.addEventListener('contextmenu', function(e) { e.preventDefault(); });
document.addEventListener('dragstart', function(e) { e.preventDefault(); });
document.addEventListener('keydown', function(e) {
  if (e.ctrlKey && (e.key === 's' || e.key === 'u' || e.key === 'S' || e.key === 'U')) e.preventDefault();
  if (e.ctrlKey && e.shiftKey && (e.key === 'I' || e.key === 'i' || e.key === 'J' || e.key === 'j' || e.key === 'C' || e.key === 'c')) e.preventDefault();
  if (e.key === 'F12') e.preventDefault();
});

// Boot: fetch DB from API then run app
(async function boot() {
  try {
    const resp = await fetch('/api/db-full', { credentials: 'same-origin' });
    if (!resp.ok) throw new Error('Failed to load data: ' + resp.status);
    var DB = await resp.json();
    var BRANDS = DB.brands;

    // Count stats
    (function() {
      var modelSet = new Set();
      DB.data.forEach(function(row) {
        BRANDS.forEach(function(b) {
          if (row[b]) {
            row[b].split('/').forEach(function(m) {
              var t = m.trim();
              if (t) modelSet.add(t.toLowerCase());
            });
          }
        });
      });
      var el = document.getElementById('modelCount');
      if (el) el.textContent = modelSet.size.toLocaleString();
    })();

    // Run app logic
\`;

const endScript = \`
  } catch(e) {
    console.error('Boot error:', e);
    document.body.innerHTML = '<div style=\"display:flex;align-items:center;justify-content:center;height:100vh;background:#07090e;color:#ff3c50;font-family:sans-serif;font-size:18px;text-align:center;padding:40px\">Failed to load. Please refresh.</div>';
  }
})();
</script>\`;

const newHtml = htmlShell + honeypot + bootScript + appLogic + endScript + '\n</body>\n</html>';

// Write to project
const outPath = 'C:/Users/JFL/Documents/vercel/triune_visualizer/public/index.html';
fs.writeFileSync(outPath, newHtml);

const origSize = fs.readFileSync('4.1.26_crossref-tool.html', 'utf8').length;
console.log('Original:', (origSize / 1024).toFixed(0), 'KB');
console.log('New:', (newHtml.length / 1024).toFixed(0), 'KB');
console.log('Reduction:', ((1 - newHtml.length / origSize) * 100).toFixed(1) + '%');
"

